import {price, percentage, series} from './data.js';
const paths={expand:'M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5',home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',chart:'M4 3v17h17M7 14l4-5 4 3 5-7',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',calendar:'M5 5h14a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2ZM7 3v4M17 3v4M3 11h18M7 15h3M14 15h3',report:'M6 3h9l4 4v14H6zM14 3v5h5M9 12h7M9 16h7',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',star:'m12 3 2.8 5.7 6.3.9-4.5 4.4 1 6.3L12 17.4l-5.6 2.9 1-6.3L3 9.6l6.2-.9Z',plus:'M12 5v14M5 12h14',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',close:'m6 6 12 12M6 18 18 6',arrow:'M5 12h14m-6-6 6 6-6 6',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18',refresh:'M20 7v5h-5M4 17v-5h5M6 6a8 8 0 0 1 13 1M5 17a8 8 0 0 0 13 1',info:'M12 11v6M12 7h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',panel:'M3 4h18v16H3zM15 4v16',filter:'M4 6h16M7 12h10M10 18h4',check:'m5 12 4 4L19 6',clock:'M12 7v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',chip:'M7 7h10v10H7zM9 3v4M15 3v4M9 17v4M15 17v4M3 9h4M3 15h4M17 9h4M17 15h4',empty:'M4 8h16v12H4zM8 8V4h8v4M9 13h6',alert:'m12 3 10 18H2ZM12 9v5M12 17h.01'};
export function icon(name,cls='') { return `<svg class="icon ${cls}" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.chart}"/></svg>`; }
export function escapeHtml(s) { return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
export function badge(s){return `<span class="stock-logo ${s.tone}" aria-hidden="true">${s.symbol}</span>`;}
export function change(value){return `<span class="change ${!Number.isFinite(value)||value===0?'neutral-text':value>0?'up':'negative'}">${percentage(value)}</span>`;}
export function starButton(s,saved){return `<button class="icon-button star-button ${saved?'saved':''}" data-action="favorite" data-id="${s.id}" aria-label="${s.name} 관심종목 ${saved?'해제':'추가'}" aria-pressed="${saved}" title="관심종목 ${saved?'해제':'추가'}">${icon('star')}</button>`;}
let chartId=0;
export function sparkline(seed,down=false,large=false,values){const points=values||series(seed,down); const width=large?660:180,height=large?240:48,pad=large?16:3;const min=Math.min(...points)-4,max=Math.max(...points)+4;const coordinates=points.map((v,i)=>`${(i/(points.length-1)*width).toFixed(1)},${(height-pad-((v-min)/(max-min))*(height-pad*2)).toFixed(1)}`);const id=`chart-${++chartId}`,color=large?'var(--brand)':down?'var(--down)':'var(--up)';return `<svg class="${large?'price-chart':'sparkline'}" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img" aria-label="${large?'선택 기간의 가격 추이':down?'하락 추세 차트':'상승 추세 차트'}"><defs><linearGradient id="${id}" x1="0" x2="0" y1="0" y2="1"><stop stop-color="${color}" stop-opacity="${large?'.16':'.1'}"/><stop offset="1" stop-color="${color}" stop-opacity="0"/></linearGradient></defs>${large?[40,95,150,205].map(y=>`<line x1="0" x2="660" y1="${y}" y2="${y}" stroke="var(--line)" stroke-dasharray="4 5"/>`).join(''):''}<path d="M0,${height} L${coordinates.join(' L')} L${width},${height} Z" fill="url(#${id})"/><polyline points="${coordinates.join(' ')}" stroke="${color}" fill="none" stroke-width="${large?2.5:1.7}" vector-effect="non-scaling-stroke"/></svg>`;}
export function heading(title,sub='',action=''){return `<div class="section-heading"><div class="heading-label"><h2>${title}</h2>${sub?`<span class="section-meta">${sub}</span>`:''}</div>${action}</div>`;}
export function stockCard(s,favorites){return `<article class="watch-card"><div class="stock-card-top"><button class="stock-identity" data-action="stock" data-id="${s.id}">${badge(s)}<span><strong>${s.name}</strong><small>${s.ticker} · ${s.exchange}</small></span></button>${starButton(s,favorites.includes(s.id))}</div><button class="stock-card-price" data-action="stock" data-id="${s.id}"><strong>${price(s)}</strong>${change(s.change)}</button></article>`;}
export function emptyState(title,message,action=''){return `<div class="empty-state">${icon('empty')}<strong>${title}</strong><p>${message}</p>${action}</div>`;}
export function skeleton(){return `<div class="skeleton-wrap" role="status" aria-label="데이터 불러오는 중">${Array.from({length:5},()=>'<div class="skeleton-row"><span class="skeleton-circle"></span><span class="skeleton-line"></span><span class="skeleton-line short"></span></div>').join('')}<span class="sr-only">데이터를 불러오고 있습니다.</span></div>`;}
